CREATE INDEX `drivers_available_unassigned_queue` ON `drivers` (`id`) WHERE "drivers"."owner_id" IS NULL AND "drivers"."blocked"=0 AND "drivers"."duplicate"=0 AND "drivers"."phone" IS NOT NULL AND json_extract("drivers"."data_json",'$.status')='available' AND COALESCE(json_extract("drivers"."data_json",'$.isDemo'),0)=0 AND json_extract("drivers"."data_json",'$.activeConversationId') IS NULL;